using TsScheduler;using TsRecommend;using System.Reflection;using System.Text.Json;
internal static class QuantumUiTests {
 static IEnumerable<Control> Desc(Control c)=>c.Controls.Cast<Control>().SelectMany(x=>new[]{x}.Concat(Desc(x)));
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);Console.WriteLine("PASS: "+name);}
 internal static int Run(){try{string root=Path.Combine(Path.GetTempPath(),"Zoo128-ui-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);ConnectionProfile.TestRoot=root;typeof(ConnectionProfiles).GetField("current",BindingFlags.Static|BindingFlags.NonPublic)!.SetValue(null,null);
 foreach(string name in new[]{"tvrock.sch","tvrock.key"})File.WriteAllText(Path.Combine(root,name),"");File.WriteAllText(Path.Combine(root,"dtv.ini"),"[TUNER1]\nAPPNAME1=record.exe\n[TUNER1 SERVICE]\nNHK=1\n",Data.Cp932);File.WriteAllText(Path.Combine(root,"connection.json"),JsonSerializer.Serialize(new{TvRockFolder=root,TvRockUrl="http://127.0.0.1:1/test/"}));File.WriteAllText(Path.Combine(root,"recommend-disabled.txt"),"off");MainForm.TestLayoutFile=Path.Combine(root,"layout.json");MainForm.TestWindowPlacementFile=Path.Combine(root,"window.json");DisplayOptions.TestPath=Path.Combine(root,"display.json");string output=Path.Combine(Environment.CurrentDirectory,"outputs","TVRockZoo-1.2.8","verification");Directory.CreateDirectory(output);
 using var form=new MainForm(false);form.Show();Application.DoEvents();foreach(var f in typeof(MainForm).GetFields(BindingFlags.NonPublic|BindingFlags.Instance))if(f.GetValue(form) is System.Windows.Forms.Timer t)t.Stop();
 var tabs=(TabControl)typeof(MainForm).GetField("_tabs",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(form)!;tabs.SelectedTab=tabs.TabPages.Cast<TabPage>().Single(x=>x.Text=="詳細設定");Application.DoEvents();
 var enabled=Desc(form).OfType<CheckBox>().Single(x=>x.Text.StartsWith("量子コンテキストで"));var weight=Desc(form).OfType<NumericUpDown>().Single(x=>x.AccessibleName=="量子認知の反映率");Check(enabled.Checked&&weight.Value==70,"Quantum context defaults ON with 70 percent weight");enabled.Checked=false;Check(!QuantumCognitionOptions.Load(root).Enabled,"Quantum OFF persists");enabled.Checked=true;weight.Value=80;Check(QuantumCognitionOptions.Load(root).Enabled&&QuantumCognitionOptions.Load(root).Weight==.8,"Quantum weight persists");weight.Value=70;Check(RecommendationOptions.Load(root).Maximum==30,"New profile uses 30 effective reservations");
 var nav=Desc(form).OfType<ListBox>().First(x=>x.DrawMode==DrawMode.OwnerDrawFixed);foreach(var item in nav.Items)if(item.ToString()!.Contains("おすすめ")){nav.SelectedItem=item;break;}Application.DoEvents();using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(output,"settings.png"));}
 var now=DateTimeOffset.Now;var booking=new Booking("test","録画時間の調整テスト","NHK",1,1,now.AddDays(1),now.AddDays(1).AddHours(1),0,true,true,false,new(){["READY"]="125",["TALE"]="35"});bool seen=false;Exception? modal=null;using var timer=new System.Windows.Forms.Timer{Interval=100};timer.Tick+=(_,_)=>{var d=Application.OpenForms.Cast<Form>().FirstOrDefault(x=>x.Text=="録画の開始・終了を調整");if(d==null)return;timer.Stop();try{var offsets=Desc(d).OfType<RecordingOffsetInput>().ToArray();Check(offsets.Length==2&&offsets[0].Value==-125&&offsets[1].Value==35,"Timing dialog preserves independent minutes and seconds");Check(Desc(d).OfType<Button>().Where(x=>x.Text is "適用" or "キャンセル").All(x=>x.Visible&&d.RectangleToClient(x.RectangleToScreen(x.ClientRectangle)).Bottom<=d.ClientSize.Height),"Timing actions fit within dialog");using var image=new Bitmap(d.Width,d.Height);d.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(Path.Combine(output,"timing.png"));seen=true;}catch(Exception e){modal=e;}finally{d.DialogResult=DialogResult.Cancel;d.Close();}};timer.Start();((Task)typeof(MainForm).GetMethod("ShowRecordingTiming",BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(form,[booking])!).GetAwaiter().GetResult();if(modal!=null)throw modal;Check(seen,"Timing dialog rendered without changing reservations");form.Close();return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
